import { BrandPack } from '../schema';

import packJson from './default.pack.json';
import legacyRolesJson from './legacy-roles.json';

/**
 * Tier 0 channel A (spec §4.3): the default pack, compiled in. The app must
 * render with zero infrastructure, so this is the floor every other channel
 * merges over — and it is the reference geometry `toMuiPalette` derives
 * non-overridden tokens from.
 *
 * `default.pack.json` and `palette.augment.d.ts` are hand-maintained source.
 * They were generated by scripts/gen-brand-tokens.mjs from the apps/elitea-ui
 * palettes; that generator went with the submodule. tokens/README.md says how
 * to edit them and why the values that are not verbatim copies are what they
 * are; __tests__/defaultPackSync.test.ts holds the copies together.
 *
 * Parsing here rather than casting is deliberate: it makes the committed
 * JSON's schema-validity a load-bearing property of every build and every
 * test run, not just of the contract test.
 */
export const DEFAULT_BRAND_PACK = BrandPack.parse(packJson);

/**
 * The per-scheme brand anchor: the token whose hue a pack's `brand.hue`
 * replaces. Derivation rotates each scheme's reference ramp by
 * `hue(pack.brand.hue) - hue(anchor of that scheme)`, so a pack that sets
 * one hue lands BOTH schemes' accents on it. That is the structural
 * resolution of §4.1 Blocker 1 (the old cyan-dark / magenta-light split).
 * Since brand guide v3 both schemes' anchor is the same Base Indigo.
 */
export const BRAND_ANCHOR_TOKEN = 'primary.main';

/** The group the 27 brand-guide roles live under in the pack: `role.<name>` (ADR-0062 decision 1). */
export const ROLE_GROUP = 'role';

/**
 * Role → its generic legacy id (ADR-0062 decision 1.4):
 * `legacy-roles.json`, `{ "<role>": ["<legacy id>"] }`.
 *
 * ADR-0024 lets a deployment hand-tune legacy ids (`scheme_tokens`); such a
 * pack does not know the roles. `resolveScheme` gives a role the first value
 * a pack tunes: the role id itself, then its legacy id. PR 4 (#3092) makes
 * theme-gate check 10 count reads of the ids on this file (decision 3.4), and
 * the stage 4 script rewrites only ids on this file (ADR-0062 Rollout).
 *
 * An id is listed only by hand and only when its meaning is the role and its
 * default colour is the role's in both schemes. A role has exactly one id, or
 * no entry: a role cannot hold two tuned colours, so a second id would lose
 * one of them. `__tests__/roles.test.ts` holds the ids, the colours and the
 * one id per role; review holds the meaning.
 */
export const LEGACY_ROLES: Readonly<Record<string, readonly string[]>> = legacyRolesJson;
